package ratelimiter

import (
	"testing"
	"time"
)

func TestBurstAllow(t *testing.T) {
	rl := NewRateLimiter(3, 1.0) // 3 token burst, 1 token/sec refill
	// First 3 calls should be allowed
	for i := 0; i < 3; i++ {
		if !rl.Allow() {
			t.Fatalf("call %d should be allowed (burst)", i+1)
		}
	}
	// 4th call should fail — burst exhausted
	if rl.Allow() {
		t.Error("4th call should be denied after burst exhausted")
	}
}

func TestRefill(t *testing.T) {
	rl := NewRateLimiter(1, 10.0) // 1 token capacity, 10 tokens/sec refill
	if !rl.Allow() {
		t.Fatal("first call should be allowed")
	}
	if rl.Allow() {
		t.Fatal("second call should be denied — no tokens")
	}
	// Sleep 200ms: at 10 tok/sec, ~2 tokens added but capped at capacity=1
	time.Sleep(200 * time.Millisecond)
	if !rl.Allow() {
		t.Error("after refill sleep, call should be allowed")
	}
}

func TestZeroCapacity(t *testing.T) {
	rl := NewRateLimiter(0, 1.0)
	if rl.Allow() {
		t.Error("zero-capacity limiter should never allow")
	}
}
